"use client";

import { loadFont } from "@remotion/google-fonts/Geist";
import { loadFont as loadMono } from "@remotion/google-fonts/GeistMono";
import type React from "react";
import { useId, useMemo } from "react";
import { AbsoluteFill, Easing, interpolate } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { useGlide } from "@/lib/remocn/glide";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  appearOf,
  FLIP_DUR,
  FLIP_START,
  flipSpan,
  gridShape,
  type UnitGridElementId,
  unitGridTimeline,
} from "./timeline";

const { fontFamily: sans } = loadFont("normal", {
  weights: ["400"],
  subsets: ["latin"],
});
const { fontFamily: mono } = loadMono("normal", {
  weights: ["400"],
  subsets: ["latin"],
});

export interface UnitGridProps {
  total?: number;
  highlighted?: number;
  caption?: string;
  accent?: string;
  /** Text color of the count and caption; overrides the theme. */
  ink?: string;
  /** Background fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the count and caption. Load it yourself; Geist by default. */
  fontFamily?: string;
  /** Frames each highlighted unit takes to flip. */
  flip?: number;
  /** Unit radius as a share of the grid pitch. */
  dotSize?: number;
  grain?: boolean;
  /** Size of the grid and copy, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  theme?: "dark" | "light";
  speed?: number;
  /**
   * Moves, trims or stretches the grid appearing, the count, the flips, the
   * caption and the settle, by the ids in `./timeline`. Frames on the scene
   * timeline, after `delay` and `speed`.
   */
  timing?: Timing<UnitGridElementId>;
}

const EASE_IO = Easing.bezier(0.65, 0, 0.35, 1);
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

const THEMES = {
  dark: {
    bg: "#0A0A0B",
    fg: "#F3F2EF",
    muted: "#8B8A90",
    unit: "#3A3A40",
    unitLit: "#4A4A51",
    back: "#1E1E22",
    light: "rgba(255,255,255,0.05)",
    // gradients.sh "limb", lit left to right across the highlighted units.
    lit: ["#e9ecff", "#8a8bff", "#4b2bd6"],
    glow: "color-mix(in oklab, #4b2bd6 26%, transparent)",
    grain: 0.06,
  },
  light: {
    bg: "#F5F4F0",
    fg: "#121214",
    muted: "#6E6C67",
    unit: "#CBC9C2",
    unitLit: "#D8D6CF",
    back: "#B9B7B0",
    light: "rgba(255,255,255,0.8)",
    lit: ["#8a8bff", "#5a3ff0", "#2f1d9e"],
    glow: "color-mix(in oklab, #8a8bff 22%, transparent)",
    grain: 0.045,
  },
} as const;

export const unitGridLength = (highlighted = 33) =>
  FLIP_START + flipSpan(highlighted) + FLIP_DUR + 18;

function mix(a: string, b: string, t: number) {
  const pa = Number.parseInt(a.slice(1), 16);
  const pb = Number.parseInt(b.slice(1), 16);
  const ch = (p: number, s: number) => (p >> s) & 255;
  const c = (s: number) =>
    Math.round(ch(pa, s) + (ch(pb, s) - ch(pa, s)) * t)
      .toString(16)
      .padStart(2, "0");
  return `#${c(16)}${c(8)}${c(0)}`;
}

function Grain({ opacity }: { opacity: number }) {
  const id = `g${useId().replace(/[^a-zA-Z0-9_-]/g, "")}`;
  return (
    <svg
      width="100%"
      height="100%"
      style={{ position: "absolute", inset: 0, opacity, pointerEvents: "none" }}
      aria-hidden
    >
      <filter id={id}>
        <feTurbulence
          type="fractalNoise"
          baseFrequency="0.9"
          numOctaves={2}
          seed={11}
          stitchTiles="stitch"
        />
        <feColorMatrix values="0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0 0.5  0 0 0 0.9 0" />
      </filter>
      <rect width="100%" height="100%" filter={`url(#${id})`} />
    </svg>
  );
}

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

export function UnitGrid(props: UnitGridProps) {
  const {
    total = 100,
    highlighted = 33,
    caption = "1 in 3 teams ship weekly",
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = sans,
    dotSize = 0.34,
    grain = true,
    scale = 1,
    delay = 0,
    theme = "dark",
    speed = 1,
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed;
  const { width: W, height: H, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    unitGridTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const u = H / 720;
  const pal = THEMES[theme];
  const fg = ink ?? pal.fg;
  const stage =
    background === "transparent" ? "transparent" : (background ?? pal.bg);
  const n = Math.max(1, Math.round(total));
  const hi = Math.max(0, Math.min(n, Math.round(highlighted)));

  const { cols, rows } = gridShape(n);
  const gridH = H * 0.56;
  const pitch = Math.min(gridH / rows, (W * 0.4) / cols);
  const gw = pitch * cols;
  const gh = pitch * rows;
  const colW = W * 0.36;
  const gap = W * 0.07;
  const left = (W - (gw + gap + colW)) / 2;
  const top = (H - gh) / 2;
  const r = pitch * dotSize;

  const appearEl = tl.get("appear");
  const flipEl = tl.get("flip");
  const span = flipEl.beat("span");
  const flip = flipEl.beat("unit");
  const flipEnd = flipEl.end;
  const settleEl = tl.get("settle");
  const countEl = tl.get("count");
  const captionEl = tl.get("caption");

  const units = useMemo(
    () =>
      Array.from({ length: n }, (_, i) => {
        const c = i % cols;
        const row = Math.floor(i / cols);
        const order = hi > 1 ? i / (hi - 1) : 0;
        return {
          i,
          x: left + (c + 0.5) * pitch,
          y: top + (row + 0.5) * pitch,
          appear: appearOf(i, cols),
          flip: i < hi ? flipEl.start + EASE_IO(order) * span : -1,
          hue: c / Math.max(1, cols - 1),
          light:
            1 -
            ((c / Math.max(1, cols - 1)) * 0.6 +
              (row / Math.max(1, rows - 1)) * 0.4),
        };
      }),
    [n, cols, rows, hi, left, top, pitch, span, flipEl],
  );

  const litAt = (k: number) =>
    k < 0.5
      ? mix(pal.lit[0], pal.lit[1], k * 2)
      : mix(pal.lit[1], pal.lit[2], (k - 0.5) * 2);
  const glowIn = interpolate(
    t,
    [flipEl.start, flipEnd + flipEl.beat("glowTail")],
    [0, 1],
    {
      ...CLAMP,
      easing: EASE_IO,
    },
  );
  let count = 0;
  const settle = interpolate(t, [settleEl.start, settleEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_IO,
  });

  const dots: React.ReactNode[] = [];
  for (const d of units) {
    const a = interpolate(
      t - appearEl.start + appearEl.beat("lead") - d.appear,
      [0, appearEl.beat("unit")],
      [0, 1],
      {
        ...CLAMP,
        easing: EASE_OUT,
      },
    );
    if (a <= 0) continue;
    let sx = 1;
    let s = 0.55 + 0.45 * a;
    let fill: string = mix(pal.unit, pal.unitLit, d.light);
    let opacity = a * (1 - settle * 0.22);
    if (d.flip >= 0) {
      const p = interpolate(t - d.flip, [0, flip], [0, 1], CLAMP);
      if (p > 0) {
        const e = EASE_IO(p);
        sx = Math.max(0.06, Math.abs(Math.cos(Math.PI * e)));
        if (e < 0.5) {
          fill = mix(fill, pal.back, e * 2);
        } else {
          count++;
          fill = mix(pal.back, litAt(d.hue), Math.min(1, (e - 0.5) * 2.6));
          opacity = a;
          const pop = Math.sin(Math.PI * Math.min(1, (e - 0.5) * 2));
          s *= 1 + 0.12 * pop;
        }
      }
    }
    dots.push(
      <ellipse
        key={d.i}
        cx={d.x}
        cy={d.y}
        rx={r * s * sx}
        ry={r * s}
        fill={fill}
        opacity={opacity}
      />,
    );
  }

  const numIn = interpolate(t, [countEl.start, countEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const capIn = interpolate(t, [captionEl.start, captionEl.end], [0, 1], {
    ...CLAMP,
    easing: EASE_OUT,
  });
  const camAt = (f: number) =>
    interpolate(f, [0, flipEnd + flipEl.beat("cameraTail")], [1, 1.03], {
      ...CLAMP,
      easing: EASE_IO,
    });
  const cam = camAt(t);
  // Weighed by the distance from the centre to the furthest text.
  const camMoving = [t - speed, t + speed].some(
    (f) => Math.abs(camAt(f) - cam) * W * 0.5 > 1e-3,
  );
  const numSize = Math.min(gh * 0.5, colW * 0.46);
  const digits = String(hi).length;
  const colLeft = left + gw + gap;

  return (
    <AbsoluteFill style={{ background: stage, overflow: "hidden" }}>
      <AbsoluteFill
        style={{
          background: `radial-gradient(ellipse 55% 60% at 40% 42%, ${pal.light}, transparent 75%)`,
        }}
      />
      <AbsoluteFill
        style={{
          opacity: glowIn,
          background: `radial-gradient(ellipse ${gw * 0.9}px ${gh * 0.55}px at ${left + gw / 2}px ${top + gh * 0.2}px, ${pal.glow}, transparent 80%)`,
        }}
      />
      <ScaleLayer scale={scale}>
        <AbsoluteFill
          style={{
            transform: `scale(${cam})${glide(camMoving)}`,
            transformOrigin: "50% 50%",
          }}
        >
          <svg
            width={W}
            height={H}
            viewBox={`0 0 ${W} ${H}`}
            style={{ position: "absolute", inset: 0 }}
            aria-hidden
          >
            {dots}
          </svg>
          <div
            style={{
              position: "absolute",
              left: colLeft,
              top: top - numSize * 0.16,
              width: colW,
              display: "flex",
              alignItems: "baseline",
              gap: 10 * u,
              color: fg,
              opacity: numIn,
              transform: `translateY(${(1 - numIn) * 14 * u}px)`,
              filter: `blur(${(1 - numIn) * 6 * u}px)`,
            }}
          >
            <span
              style={{
                fontFamily,
                fontWeight: 400,
                fontSize: numSize,
                lineHeight: 1,
                letterSpacing: "-0.04em",
                fontVariantNumeric: "tabular-nums",
                width: `calc(${digits}ch - ${digits * 0.04}em)`,
                textAlign: "right",
                flexShrink: 0,
              }}
            >
              {count}
            </span>
            <span
              style={{
                fontFamily: mono,
                fontWeight: 400,
                fontSize: numSize * 0.22,
                lineHeight: 1,
                letterSpacing: "-0.01em",
                fontVariantNumeric: "tabular-nums",
                color: pal.muted,
              }}
            >
              / {n}
            </span>
          </div>
          <div
            style={{
              position: "absolute",
              left: colLeft,
              top,
              width: colW,
              height: gh,
              display: "flex",
              flexDirection: "column",
              justifyContent: "flex-end",
            }}
          >
            <div
              style={{
                width: colW * EASE_IO(capIn),
                height: Math.max(1, u),
                marginBottom: 20 * u,
                background: accent,
                opacity: 0.8,
              }}
            />
            <div
              style={{
                fontFamily,
                fontWeight: 400,
                fontSize: 34 * u,
                lineHeight: 1.15,
                letterSpacing: "-0.02em",
                textWrap: "balance",
                color: fg,
                opacity: capIn,
                transform: `translateY(${(1 - capIn) * 12 * u}px)`,
                filter: `blur(${(1 - capIn) * 5 * u}px)`,
              }}
            >
              {caption}
            </div>
          </div>
        </AbsoluteFill>
      </ScaleLayer>
      {grain ? <Grain opacity={pal.grain} /> : null}
    </AbsoluteFill>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// The grid's units appearing in a diagonal wave, the count rising, the
// highlighted units flipping over to the lit side, the caption landing and
// the grid settling. Frames on the 30 fps scene timeline, after `delay` and
// `speed`. The ids are public: a saved `timing` prop refers to them.

export type UnitGridElementId =
  | "appear"
  | "count"
  | "flip"
  | "caption"
  | "settle";

export interface UnitGridTimingProps {
  total?: number;
  highlighted?: number;
  /** Frames each highlighted unit takes to flip. */
  flip?: number;
}

export const APPEAR_STEP = 0.9;
const APPEAR_DUR = 12;
/** Frames the appear wave runs ahead of the scene's first frame. */
const APPEAR_LEAD = 4;
export const FLIP_START = 34;
export const FLIP_DUR = 10;

/** Frames the flips spread over, first unit to last. */
export function flipSpan(n: number) {
  return Math.min(60, Math.max(10, 8 + n * 0.9));
}

export function hash(n: number) {
  const x = Math.sin(n * 127.1 + 311.7) * 43758.5453;
  return x - Math.floor(x);
}

export function gridShape(total: number) {
  if (total === 100) return { cols: 10, rows: 10 };
  const cols = Math.max(1, Math.ceil(Math.sqrt(total)));
  return { cols, rows: Math.ceil(total / cols) };
}

/** Frame (before the lead) unit `i` of a grid `cols` wide starts appearing. */
export function appearOf(i: number, cols: number) {
  const c = i % cols;
  const row = Math.floor(i / cols);
  return (c + row) * APPEAR_STEP + hash(i + 1.3) * 2;
}

// `appear` is the grid's units fading in, each over `unit` frames, in a
// diagonal wave running `lead` frames ahead. `count` is the count rising.
// `flip` is the highlighted units flipping, spread over `span` with each
// unit turning over `unit`; the glow keeps growing `glowTail` frames after
// it and the camera push runs `cameraTail` past it. `caption` lands around
// the last flip and `settle` dims the rest of the grid; both follow `flip`.
export const unitGridTimeline = defineTimeline<
  UnitGridElementId,
  UnitGridTimingProps
>(({ total = 100, highlighted = 33, flip = FLIP_DUR }) => {
  const n = Math.max(1, Math.round(total));
  const hi = Math.max(0, Math.min(n, Math.round(highlighted)));
  const { cols } = gridShape(n);
  let lastAppear = 0;
  for (let i = 0; i < n; i++)
    lastAppear = Math.max(lastAppear, appearOf(i, cols));
  const span = flipSpan(hi);
  const flipEnd = FLIP_START + span + flip;
  const out: TimelineElement<UnitGridElementId>[] = [
    {
      id: "appear",
      lane: "Grid",
      label: "appear",
      start: 0,
      length: Math.max(0, lastAppear - APPEAR_LEAD + APPEAR_DUR),
      beats: { lead: APPEAR_LEAD, unit: APPEAR_DUR },
    },
    { id: "count", lane: "Copy", label: "count", start: 16, length: 18 },
    {
      id: "flip",
      lane: "Grid",
      label: "flip",
      start: FLIP_START,
      // Written so that `start + length` is `flipEnd` to the last bit.
      length: flipEnd - FLIP_START,
      beats: { span, unit: flip, glowTail: 10, cameraTail: 40 },
    },
    {
      id: "caption",
      lane: "Copy",
      label: "caption",
      start: flipEnd - 8,
      length: 20,
      follows: "flip",
    },
    {
      id: "settle",
      lane: "Grid",
      label: "settle",
      start: flipEnd,
      length: 22,
      follows: "flip",
    },
  ];
  return out;
});
